import { rehypeSyntaxHighlighting, } from '@mintlify/mdx/plugins';
import rehypeKatex from 'rehype-katex';
import remarkSmartypants from 'remark-smartypants';
/**
 * The plugins `serialize` from `@mintlify/mdx/server` wraps around `getMDXOptions`' lists.
 * `remarkMdxExpandExpressions` needs the same set so `<MDX>` fragments compile like page content;
 * it lives here because `rehypeSyntaxHighlighting` is server-only and `getMDXOptions` is bundled
 * for the client.
 */
export const getSerializeExtras = (syntaxHighlightingOptions) => ({
    remarkPlugins: [remarkSmartypants],
    rehypePlugins: [rehypeKatex, [rehypeSyntaxHighlighting, syntaxHighlightingOptions]],
});
